css:
*{
    font-size: 11px;
}

  /* ===== GLOBAL SETTINGS ===== */
  @page {
    size: A4;
    margin: 5mm; /* Narrow margins for single page */
  }

  html, body { margin: 0; padding: 0; }
  *, *::before, *::after { box-sizing: border-box; }

  .wrap {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px; /* Smaller font for better fit */
    color: #111;
    width: 100%;
    line-height: 1.3;
  }

  .page {
    width: 100%;
    max-width: 200mm;
    margin: 0 auto;
  }

  /* ===== HEADER & LOGO ===== */
  .letter-head img {
    max-width: 100%;
    height: auto;
    max-height: 30mm; /* Limit logo height */
  }

  .title {
    text-align: center;
    font-weight: 800;
    font-size: 15px;
    margin: 5px 0;
    text-decoration: underline;
  }

  /* ===== INFO CARD ===== */
  .info-card {
    border: 1px solid #777;
    padding: 5px;
    margin-bottom: 8px;
  }
  .info-table { width: 100%; border-collapse: collapse; }
  .info-table td { padding: 2px 4px; vertical-align: top; }
  
  .k { font-weight: 700; color: #333; }
  .v { font-weight: 600; color: #000; }

  /* ===== RESULTS TABLE ===== */
  .section-bar {
    background: #f0f0f0;
    border: 1px solid #777;
    border-bottom: none;
    font-weight: 800;
    text-align: center;
    padding: 4px;
    font-size: 11px;
    margin-top: 8px;
    text-transform: uppercase;
  }

  .tbl {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 5px;
  }
  .tbl th, .tbl td {
    border: 1px solid #777;
    padding: 3px 6px; /* Tight padding */
    vertical-align: middle;
  }
  .tbl th {
    background: #e0e0e0;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
  }
  .tbl tbody tr:nth-child(even) { background: #fafafa; }
  
  .center { text-align: center; }
  .muted { color: #555; }

  /* ===== FOOTER ===== */
  .footer {
    margin-top: 15px;
    display: flex;
    justify-content: space-between;
    gap: 20px;
    page-break-inside: avoid;
  }
  .sign {
    flex: 1;
    border-top: 1px solid #333;
    padding-top: 5px;
    font-weight: 700;
    text-align: center;
  }

  .end {
    margin-top: 10px;
    text-align: center;
    font-weight: 800;
    font-size: 10px;
    border-top: 1px dotted #ccc;
    padding-top: 5px;
  }

  @media print {
    body { -webkit-print-color-adjust: exact; }
    .page { page-break-after: avoid; }
  }

html:
{% if doc.docstatus == 1 %}
{% set role_profile = frappe.db.get_value("User", frappe.session.user, "role_profile_name") %}
{% if role_profile in ["lab", "Lab", "Admin", "Rasiin Users", "Lab Supervisor", "Doctor"] or frappe.session.user == "Administrator" %}

<div class="wrap">
  <div class="page">

    {# --- HEADER --- #}
    <div style="display: flex; justify-content: center; margin-bottom: 5px;">
      {% if letter_head and not no_letterhead -%}
        <div class="letter-head text-center" style="width:100%; display: flex; justify-content: center;">{{ letter_head }}</div>
      {%- else -%}
        {% set logo = frappe.db.get_value('Letter Head', 'logo', 'image') %}
        {% if logo %}
          <div class="text-center"><img src="{{ logo }}" style="max-height: 25mm; width: auto;"/></div>
        {% endif %}
      {%- endif %}
    </div>

    {# --- TITLE --- #}
    <div class="title">{{ doc.template or doc.lab_test_name or "Lab Report" }}</div>

    {# --- PATIENT INFO --- #}
    {% set p = frappe.get_doc("Patient", doc.patient) if doc.patient else None %}
    {% set sex = p.sex if p else (doc.patient_sex or "") %}
    {% set age = (p.p_age if p else "") %}
    {% set age_type = (p.age_type if p else "") %}
    {% set patient_name = p.patient_name if p else "" %}

    <div class="info-card">
      <table class="info-table">
        <tr>
          <td style="width:55%;">
            <div><span class="k">Patient Name</span> : <span class="v">{{ patient_name }}</span></div>
            <div><span class="k">Patient ID</span> : <span class="v">{{ doc.patient or "" }}</span></div>
            <div><span class="k">Sex / Age</span> : <span class="v">{{ sex }}{% if age %} / {{ age }} {{ age_type }}s{% endif %}</span></div>
            <div><span class="k">Doctor</span> : <span class="v">{{ doc.practitioner or doc.practitioner_name or doc.referring_practitioner_name or "" }}</span></div>
          </td>
          <td style="width:45%;">
            <div><span class="k">Lab Ref No</span> : <span class="v">{{ doc.lab_ref or "" }}</span></div>
            <div><span class="k">Collected</span> : <span class="v">{{ doc.date or "" }} {% if doc.time_collected %}{{ frappe.format(doc.time_collected, "Time") }}{% endif %}</span></div>
            <div><span class="k">Reported</span> : <span class="v">{{ doc.date or "" }} {% if doc.time_reported %}{{ frappe.format(doc.time_reported, "Time") }}{% endif %}</span></div>
            <div><span class="k">Printed</span> : <span class="v">{{ frappe.utils.now_datetime() }}</span></div>
          </td>
        </tr>
      </table>
    </div>

    {# --- RESULTS BODY --- #}
    {% set groups = doc.get_lab_tests_for_all() if doc.get_lab_tests_for_all else None %}

    <div class="results-area">
      {% if groups %}
        {% for group_name, rows in groups.items() %}
          <div class="section-bar">{{ group_name }} Report</div>
          <table class="tbl">
            <thead>
              <tr>
                <th style="width:45%;">Test</th>
                <th style="width:25%;">Result</th>
                <th style="width:30%;">Normal Range</th>
              </tr>
            </thead>
            <tbody>
              {% for r in rows %}
                {% if r.result_value or r.result_value == 0 %}
                  <tr>
                    <td>{{ r.test or r.lab_test_name or "" }}</td>
                    <td style="font-weight:bold;">{{ r.result_value }} <span style="font-size:0.85em; font-weight:normal;">{{ r.lab_test_uom or "" }}</span></td>
                    <td class="center">{{ r.normal_range or "" }}</td>
                  </tr>
                {% endif %}
              {% endfor %}
            </tbody>
          </table>
        {% endfor %}
      {% else %}
        <div class="section-bar">{{ doc.lab_test_name or "Lab" }} Report</div>
        <table class="tbl">
          <thead>
            <tr>
              <th style="width:45%;">Test</th>
              <th style="width:25%;">Result</th>
              <th style="width:30%;">Normal Range</th>
            </tr>
          </thead>
          <tbody>
            {% for r in doc.normal_test_items %}
              {% if r.result_value %}
                <tr>
                  <td>
                    {% if r.lab_test_name %}<b>{{ r.lab_test_name }}</b>{% endif %}
                    {% if r.lab_test_event %}<div class="muted" style="font-size:0.85em">{{ r.lab_test_event }}</div>{% endif %}
                  </td>
                  <td style="font-weight:bold;">{{ r.result_value }} <span style="font-size:0.85em; font-weight:normal;">{{ r.lab_test_uom or "" }}</span></td>
                  <td class="center">{{ r.normal_range or "" }}</td>
                </tr>
              {% endif %}
            {% endfor %}
          </tbody>
        </table>
      {% endif %}
    </div>

    {# --- COMMENTS --- #}
    {% if doc.lab_test_comment %}
      <div style="margin-top:8px; border:1px solid #ddd; padding:4px;">
        <b>Comments:</b> <span class="muted">{{ doc.lab_test_comment }}</span>
      </div>
    {% endif %}

    {# --- FOOTER --- #}
    {# Uncomment below if you want signatures back #}
    
    <div class="footer">
      <div class="sign">
        Reported By<br>
        <span class="muted">{{ frappe.get_fullname() }}</span>
      </div>
      <div class="sign">
        Authorized By<br>
        <span class="muted">
          {{ doc.employee_name or "" }}
          {% if doc.employee_designation %}<br>{{ doc.employee_designation }}{% endif %}
        </span>
      </div>
    </div>
    

    <div class="end">*** End of Report ***</div>

  </div>
</div>

{% else %}
  <div style="padding:10px; border:1px solid #999; color:red;"><b>Not allowed to print.</b></div>
{% endif %}
{% else %}
  <div style="padding:10px; border:1px solid #999; color:red;"><b>Please Submit if Results are Completed.</b></div>
{% endif %}
